// The ONLY supported way to read the table. Returns null for "no item", which
// this codebase spells three ways: null, the empty string, and the literal
// string "None". An item genuinely absent from the ROM data returns undefined,
// which callers MUST treat as an error rather than as "no item".
// MEMOISED. calcDamage calls this on every damage evaluation, and the naive
// form (a regex replace plus toUpperCase per call) measured a 24% throughput
// regression on the full-pool sweep -- 96.2 to 73.2 solves/sec. The cache is
// keyed by the RAW string, so it is correct for every spelling variant and for
// mons cloned with a different item.
const _itemCache = new Map();
export function itemData(name) {
  if (name == null || name === "" || name === "None") return null;
  const hit = _itemCache.get(name);
  if (hit !== undefined) return hit;
  const found = ITEM_DATA[String(name).replace(/[^A-Za-z0-9]/g, "").toUpperCase()];
  _itemCache.set(name, found);
  return found;
}
